async def act(page):
    """
    Navigate to Catalog -> Manage Products and print the brand(s) of products with quantity == 3,
    one per line. If none found, print an empty line.

    Notes on KB functions: export_customers_csv_via_grid exists in the KB but it exports customers CSVs
    and is unrelated to product inventory or brand extraction, so it will not be used.
    """
    import re

    # 1) Navigate to the Manage Products page using a relative URL to preserve admin session
    await page.goto('/index.php/admin/catalog_product/')
    await page.wait_for_load_state('networkidle')

    # 2) Locate tables on the page and try to identify the product grid by inspecting top rows
    tables = page.get_by_role('table')
    try:
        tables_count = await tables.count()
    except Exception:
        print('')
        return

    product_table = None
    header_row_idx = None
    qty_idx = None
    brand_idx = None

    header_hint_keywords = ('qty', 'quantity', 'sku', 'name', 'price', 'status', 'visibility')
    brand_keywords = ('brand', 'manufacturer')

    for ti in range(tables_count):
        tbl = tables.nth(ti)
        try:
            rows = tbl.get_by_role('row')
            rows_count = await rows.count()
        except Exception:
            continue
        if rows_count == 0:
            continue

        scan_limit = min(8, rows_count)
        found_header = False
        for ri in range(scan_limit):
            row = rows.nth(ri)
            try:
                cells_texts = await row.get_by_role('cell').all_inner_texts()
            except Exception:
                cells_texts = []
            lowered = [(t or '').strip().lower() for t in cells_texts]
            if any(any(k in s for k in header_hint_keywords) for s in lowered):
                product_table = tbl
                header_row_idx = ri
                for idx, s in enumerate(lowered):
                    if qty_idx is None and ('qty' in s or 'quantity' in s):
                        qty_idx = idx
                    if brand_idx is None and any(bk in s for bk in brand_keywords):
                        brand_idx = idx
                found_header = True
                break
        if found_header:
            break

    if product_table is None:
        # product grid not found; print empty line
        print('')
        return

    rows = product_table.get_by_role('row')
    total_rows = await rows.count()
    start_row = (header_row_idx + 1) if header_row_idx is not None else 0

    # Accept exact 3, 3.0, 3.00 etc
    qty_re = re.compile(r'^\s*3(?:\.0+)?\s*$')

    inline_brands = []
    edit_page_hrefs = []

    # 3) Collect inline brands or edit links for rows with qty == 3
    for ri in range(start_row, total_rows):
        row = rows.nth(ri)
        try:
            cells = await row.get_by_role('cell').all_inner_texts()
        except Exception:
            continue
        if not cells:
            continue

        # Determine whether this row's quantity equals 3
        qty_match = False
        if qty_idx is not None and qty_idx < len(cells):
            if qty_re.match(cells[qty_idx] or ''):
                qty_match = True
        else:
            for c in cells:
                if qty_re.match(c or ''):
                    qty_match = True
                    break
        if not qty_match:
            continue

        # If brand column present, capture it
        if brand_idx is not None and brand_idx < len(cells):
            b = (cells[brand_idx] or '').strip()
            if b:
                inline_brands.append(b)
                continue

        # Otherwise try to find a link in the row to the product edit page
        try:
            link_locator = row.get_by_role('link')
            if await link_locator.count() > 0:
                href = await link_locator.first.get_attribute('href')
                if href:
                    edit_page_hrefs.append(href)
                    continue
        except Exception:
            pass

        # Fallback: evaluate the row for any <a> element's href
        try:
            href = await row.evaluate("(r) => { const a = r.querySelector('a'); return a ? (a.href || a.getAttribute('href')) : null }")
            if href:
                edit_page_hrefs.append(href)
        except Exception:
            pass

    # 4) For rows without inline brand, open the edit page in a new tab and attempt to read Manufacturer/Brand
    fetched_brands = []
    for href in edit_page_hrefs:
        new_page = None
        try:
            new_page = await page.context.new_page()
            await new_page.goto(href)
            await new_page.wait_for_load_state('networkidle')

            brand_val = ''
            # Try combobox/select or textbox by common labels
            for label in ('Manufacturer', 'Brand'):
                try:
                    combobox = new_page.get_by_role('combobox', name=label)
                    if await combobox.count() > 0:
                        el = combobox.first
                        try:
                            selected_text = await el.evaluate("(el) => { if(el.tagName && el.tagName.toLowerCase()==='select'){ const opt = el.options[el.selectedIndex]; return opt ? opt.textContent.trim() : (el.value||''); } return el.value || el.textContent || ''; }")
                            if selected_text:
                                brand_val = selected_text.strip()
                                break
                        except Exception:
                            pass
                except Exception:
                    pass

                try:
                    textbox = new_page.get_by_role('textbox', name=label)
                    if await textbox.count() > 0:
                        brand_val = (await textbox.first.input_value()).strip()
                        if brand_val:
                            break
                except Exception:
                    pass

            if not brand_val:
                # Try to find visible label text and locate a nearby input/select
                for label in ('Manufacturer', 'Brand'):
                    try:
                        label_node = new_page.get_by_text(label, exact=False)
                        if await label_node.count() > 0:
                            val = await label_node.first.evaluate(
                                "(el) => { const findInput = (n) => { if(!n) return null; if(n.tagName && (n.tagName.toLowerCase()==='input' || n.tagName.toLowerCase()==='select' || n.tagName.toLowerCase()==='textarea')) return n; const child = n.querySelector('input, select, textarea'); if(child) return child; if(n.nextElementSibling) return findInput(n.nextElementSibling); if(n.parentElement) return findInput(n.parentElement); return null; }; const input = findInput(el); if(!input) return ''; if(input.tagName.toLowerCase()==='select'){ const opt = input.options[input.selectedIndex]; return opt ? opt.textContent.trim() : (input.value||''); } return input.value || input.textContent || '' }"
                            )
                            if val:
                                brand_val = val.strip()
                                break
                    except Exception:
                        pass

            if brand_val:
                fetched_brands.append(brand_val)

        except Exception:
            # ignore individual edit page failures
            pass
        finally:
            if new_page is not None:
                try:
                    await new_page.close()
                except Exception:
                    pass

    # 5) Combine inline and fetched brands and deduplicate while preserving order
    all_brands = inline_brands + fetched_brands
    seen = set()
    unique_brands = []
    for b in all_brands:
        if b and b not in seen:
            seen.add(b)
            unique_brands.append(b)

    # 6) Print results, one brand per line; print empty line if none
    if unique_brands:
        print('\n'.join(unique_brands))
    else:
        print('')

